#include "aes_gcm.h"
#include "../include/os_aes_ct.h"
/* Lot 73: S-box through the bitsliced constant-time circuit (no table). */
static const uint8_t rcon[10]={1,2,4,8,16,32,64,128,27,54};
static uint8_t xtime(uint8_t value){return os_aes_ct_xtime(value);}
static uint8_t mul(uint8_t a,uint8_t b){uint8_t result=0U;while(b){if(b&1U)result^=a;a=xtime(a);b>>=1U;}return result;}
static void add_round_key(uint8_t state[16],const uint8_t* key){uint8_t i;for(i=0U;i<16U;i++)state[i]^=key[i];}
static void sub_bytes(uint8_t state[16]){os_aes_ct_sub16(state);}
static void shift_rows(uint8_t state[16]){uint8_t t[16],i;for(i=0U;i<16U;i++)t[i]=state[i];state[0]=t[0];state[4]=t[4];state[8]=t[8];state[12]=t[12];state[1]=t[5];state[5]=t[9];state[9]=t[13];state[13]=t[1];state[2]=t[10];state[6]=t[14];state[10]=t[2];state[14]=t[6];state[3]=t[15];state[7]=t[3];state[11]=t[7];state[15]=t[11];}
static void mix_columns(uint8_t state[16]){uint8_t c,a,b,d,e;for(c=0U;c<4U;c++){a=state[4U*c];b=state[4U*c+1U];d=state[4U*c+2U];e=state[4U*c+3U];state[4U*c]=(uint8_t)(mul(a,2U)^mul(b,3U)^d^e);state[4U*c+1U]=(uint8_t)(a^mul(b,2U)^mul(d,3U)^e);state[4U*c+2U]=(uint8_t)(a^b^mul(d,2U)^mul(e,3U));state[4U*c+3U]=(uint8_t)(mul(a,3U)^b^d^mul(e,2U));}}
int aes128_init(aes128_ctx_t* context,const uint8_t key[16]){uint8_t i,temp[4],bytes=16U,round=0U; if(!context||!key)return -1;for(i=0U;i<16U;i++)context->round_keys[i]=key[i];while(bytes<176U){for(i=0U;i<4U;i++)temp[i]=context->round_keys[(uint8_t)(bytes-4U+i)];if((bytes&15U)==0U){uint8_t x=temp[0];temp[0]=temp[1];temp[1]=temp[2];temp[2]=temp[3];temp[3]=x;os_aes_ct_sub4(temp);temp[0]^=rcon[round++];}for(i=0U;i<4U;i++){context->round_keys[bytes]=(uint8_t)(context->round_keys[(uint8_t)(bytes-16U)]^temp[i]);bytes++;}}return 0;}
int aes128_encrypt_block(const aes128_ctx_t* context,const uint8_t input[16],uint8_t output[16]){uint8_t state[16],i,round;if(!context||!input||!output)return -1;for(i=0U;i<16U;i++)state[i]=input[i];add_round_key(state,context->round_keys);for(round=1U;round<10U;round++){sub_bytes(state);shift_rows(state);mix_columns(state);add_round_key(state,context->round_keys+16U*round);}sub_bytes(state);shift_rows(state);add_round_key(state,context->round_keys+160U);for(i=0U;i<16U;i++)output[i]=state[i];return 0;}
static void xor_block(uint8_t left[16],const uint8_t right[16]){uint8_t i;for(i=0U;i<16U;i++)left[i]^=right[i];}
static void shift_right_one(uint8_t value[16]){uint8_t i,carry=0U,next;for(i=0U;i<16U;i++){next=(uint8_t)(value[i]&1U);value[i]=(uint8_t)((value[i]>>1U)|(carry<<7U));carry=next;}}
static void ghash_multiply(uint8_t value[16],const uint8_t hash[16]){uint8_t z[16]={0},v[16],i;for(i=0U;i<16U;i++)v[i]=hash[i];for(i=0U;i<128U;i++){uint8_t j,bit=(uint8_t)(0U-(uint8_t)((value[i>>3U]>>(7U-(i&7U)))&1U)),lsb=(uint8_t)(0U-(uint8_t)(v[15]&1U));for(j=0U;j<16U;j++)z[j]^=(uint8_t)(v[j]&bit);shift_right_one(v);v[0]^=(uint8_t)(225U&lsb);}for(i=0U;i<16U;i++)value[i]=z[i];}
static void put64(uint8_t output[8],uint64_t value){uint8_t i;for(i=0U;i<8U;i++)output[i]=(uint8_t)(value>>(56U-8U*i));}
static void ghash_update(uint8_t state[16],const uint8_t hash[16],const uint8_t* data,uint16_t length){uint8_t block[16],i;while(length>=16U){xor_block(state,data);ghash_multiply(state,hash);data+=16U;length=(uint16_t)(length-16U);}if(length){for(i=0U;i<16U;i++)block[i]=0U;for(i=0U;i<length;i++)block[i]=data[i];xor_block(state,block);ghash_multiply(state,hash);}}
static void ghash(const uint8_t hash[16],const uint8_t* additional,uint16_t additional_length,const uint8_t* ciphertext,uint16_t ciphertext_length,uint8_t output[16]){uint8_t lengths[16]={0},i;for(i=0U;i<16U;i++)output[i]=0U;if(additional_length)ghash_update(output,hash,additional,additional_length);if(ciphertext_length)ghash_update(output,hash,ciphertext,ciphertext_length);put64(lengths,(uint64_t)additional_length*8U);put64(lengths+8U,(uint64_t)ciphertext_length*8U);xor_block(output,lengths);ghash_multiply(output,hash);}
static void increment_counter(uint8_t counter[16]){uint8_t i;for(i=16U;i>12U;i--){counter[i-1U]++;if(counter[i-1U])break;}}
static void make_j0(uint8_t output[16],const uint8_t fixed_iv[4],const uint8_t explicit_nonce[8]){uint8_t i;for(i=0U;i<4U;i++)output[i]=fixed_iv[i];for(i=0U;i<8U;i++)output[4U+i]=explicit_nonce[i];output[12]=0U;output[13]=0U;output[14]=0U;output[15]=1U;}
static void ctr_crypt(const aes128_ctx_t* context,const uint8_t j0[16],const uint8_t* input,uint16_t length,uint8_t* output){uint8_t counter[16],stream[16],i,take;for(i=0U;i<16U;i++)counter[i]=j0[i];while(length){increment_counter(counter);aes128_encrypt_block(context,counter,stream);take=length>16U?16U:(uint8_t)length;for(i=0U;i<take;i++)output[i]=(uint8_t)(input[i]^stream[i]);input+=take;output+=take;length=(uint16_t)(length-take);}}
static int initialize_gcm(aes128_ctx_t* context,const uint8_t key[16],const uint8_t fixed_iv[4],const uint8_t explicit_nonce[8],uint8_t hash[16],uint8_t j0[16]){uint8_t zero[16]={0};if(!key||!fixed_iv||!explicit_nonce)return -1;if(aes128_init(context,key)!=0)return -2;aes128_encrypt_block(context,zero,hash);make_j0(j0,fixed_iv,explicit_nonce);return 0;}
int aes128_gcm_encrypt(const uint8_t key[16],const uint8_t fixed_iv[4],const uint8_t explicit_nonce[8],const uint8_t* additional_data,uint16_t additional_length,const uint8_t* plaintext,uint16_t plaintext_length,uint8_t* ciphertext,uint8_t tag[16]){aes128_ctx_t context;uint8_t hash[16],j0[16],auth[16],mask[16],i;if((!additional_data&&additional_length)||(!plaintext&&plaintext_length)||(!ciphertext&&plaintext_length)||!tag)return -1;if(initialize_gcm(&context,key,fixed_iv,explicit_nonce,hash,j0)!=0)return -2;if(plaintext_length)ctr_crypt(&context,j0,plaintext,plaintext_length,ciphertext);ghash(hash,additional_data,additional_length,ciphertext,plaintext_length,auth);aes128_encrypt_block(&context,j0,mask);for(i=0U;i<16U;i++)tag[i]=(uint8_t)(auth[i]^mask[i]);return 0;}
int aes128_gcm_decrypt(const uint8_t key[16],const uint8_t fixed_iv[4],const uint8_t explicit_nonce[8],const uint8_t* additional_data,uint16_t additional_length,const uint8_t* ciphertext,uint16_t ciphertext_length,const uint8_t tag[16],uint8_t* plaintext){aes128_ctx_t context;uint8_t hash[16],j0[16],auth[16],mask[16],difference=0U,i;if((!additional_data&&additional_length)||(!ciphertext&&ciphertext_length)||(!plaintext&&ciphertext_length)||!tag)return -1;if(initialize_gcm(&context,key,fixed_iv,explicit_nonce,hash,j0)!=0)return -2;ghash(hash,additional_data,additional_length,ciphertext,ciphertext_length,auth);aes128_encrypt_block(&context,j0,mask);for(i=0U;i<16U;i++)difference|=(uint8_t)(tag[i]^auth[i]^mask[i]);if(difference)return -3;if(ciphertext_length)ctr_crypt(&context,j0,ciphertext,ciphertext_length,plaintext);return 0;}
